insert into regulations (slug, title, category, summary, doc_number, authority, issued_date, status, status_note, source_url, source_filename, relevance, sort_order, published, featured, file_size_kb, download_url) values ('dgms-tech-circular-05-2026-transport-machinery-otr-tyre-safety', 'DGMS (Tech) Circular 05 of 2026 — Safety measures for trucks, tippers, dumpers and OTR tyre handling', 'dgms_circular', 'Addressed to owners, agents and managers of all coal and metalliferous mines. Citing an alarming rise in accidents involving wheeled trackless transportation machinery — dumpers, tippers and trucks — DGMS notes that over 2023-2025 such machinery accounted for 39 of the fatal accidents in coal mines (33%), and that in 2026 up to 31 July it accounted for 36% of coal-mine fatal accidents. The circular strengthens the required safety measures for operating this machinery and for off-the-road (OTR) tyre handling operations.', 'DGMS (Tech) Circular No. MHQ/2026/05', 'DGMS', '2026-08-04', 'in_force', null, 'https://www.dgms.gov.in/writereaddata/UploadFile/Circular05_04082026.pdf', 'Circular05_04082026.pdf', 3, 230, true, false, 489, 'https://docs.mangalamcoal.com/regs/dgms-tech-circular-05-2026-transport-machinery-otr-tyre-safety.pdf')
  on conflict (slug) do update set title = excluded.title, category = excluded.category, summary = excluded.summary, doc_number = excluded.doc_number, authority = excluded.authority, issued_date = excluded.issued_date, status = excluded.status, status_note = excluded.status_note, source_url = excluded.source_url, source_filename = excluded.source_filename, relevance = excluded.relevance, sort_order = excluded.sort_order, published = excluded.published, featured = excluded.featured, file_size_kb = excluded.file_size_kb, download_url = excluded.download_url;
